select
id,order_id,order_type,customer_name,order_code,workorder_code,product_id,product_model,product_specification,routing_id,routing_name,weight,wiredrawing_scheduling_weight,enamelling_scheduling_weight,annealing_scheduling_weight,doublewire_scheduling_weight,strandedwire_scheduling_weight,tinning_scheduling_weight,measure_id,measure_name,pay_time,status,is_deleted,version,create_by,create_time,update_by,update_time,attr1,attr2,attr3
from mes_product_workorder

    is_deleted = 0
     and id = #{id}
     and order_id = #{orderId}
     and order_type = #{orderType}
     and customer_name = #{customerName}
     and order_code = #{orderCode}
     and workorder_code = #{workorderCode}
     and product_model = #{productModel}
     and product_specification = #{productSpecification}
     and routing_id = #{routingId}
     and routing_name = #{routingName}
     and weight = #{weight}
     and wiredrawing_scheduling_weight = #{wiredrawingSchedulingWeight}
     and enamelling_scheduling_weight = #{enamellingSchedulingWeight}
     and annealing_scheduling_weight = #{annealingSchedulingWeight}
     and doublewire_scheduling_weight = #{doublewireSchedulingWeight}
     and strandedwire_scheduling_weight = #{strandedwireSchedulingWeight}
     and tinning_scheduling_weight = #{tinningSchedulingWeight}
     and measure_id = #{measureId}
     and measure_name = #{measureName}
     and pay_time = #{payTime}
     and status = #{status}
     and is_deleted = #{isDeleted}
     and version = #{version}
     and create_by = #{createBy}
     and create_time = #{createTime}
     and update_by = #{updateBy}
     and update_time = #{updateTime}
     and attr1 = #{attr1}
     and attr2 = #{attr2}
     and attr3 = #{attr3}
     and product_id = #{productId}

        AND date_format(create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        AND date_format(create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


    ${params.dataScope}

order by status asc, create_time desc

